<template>
  <div class="conversa-example conversa-surface" aria-label="Interactive Conversa therapy example" data-analytics-ignore>
    <header class="conversation-header"><ConversaBrand compact /><span class="fictional-tag">Fictional practice</span><button type="button" @click="reset">↻ Reset example</button></header>
    <div class="conversation-channels" role="group" aria-label="Example conversation channels"><button v-for="item in channels" :key="item.id" type="button" :aria-pressed="channel === item.id" @click="channel = item.id; selectFirst()"><ConversaIcon :type="item.id" :size="16" />{{ item.label }}</button></div>
    <div class="conversation-layout">
      <aside class="conversation-folders" aria-label="Example inbox folders"><strong>Meadowbrook Therapy</strong><button type="button" :aria-pressed="folder === 'all'" @click="folder='all'; selectFirst()"><ConversaIcon type="all" />Inbox <span>3</span></button><button type="button" :aria-pressed="folder === 'unread'" @click="folder='unread'; selectFirst()"><ConversaIcon type="unread" />Unread <span>2</span></button><p>Care conversations<br>and team coordination,<br>in one workspace.</p></aside>
      <section class="conversation-list" aria-label="Fictional conversations"><h3>Inbox</h3><label><span class="sr-only">Search example conversations</span><input v-model="search" type="search" placeholder="Search conversations…" @input="selectFirst" /></label><button v-for="item in visible" :key="item.id" type="button" :class="{selected: selected === item.id}" :aria-pressed="selected === item.id" @click="selected = item.id"><div class="conversation-row-heading"><ConversaSender avatar-only :name="item.person" /><div><strong>{{ item.person }}</strong><span>{{ item.subject }}</span></div></div><p>{{ item.preview }}</p><ConversaBadge :type="item.channel" /><small>{{ item.unread ? 'Unread' : 'Read' }} · Example</small></button><p v-if="!visible.length" class="empty-conversations">No example conversations match. Clear the search or try All.</p></section>
      <section class="conversation-reader" aria-label="Selected fictional conversation">
        <template v-if="active"><div class="conversation-reader-heading"><div><p>MEADOWBROOK THERAPY</p><h3>{{ active.subject }}</h3></div><ConversaBadge :type="active.channel" /></div>
          <SecureMessageBanner v-if="active.channel === 'secure'" :shared="true" />
          <p v-else-if="active.channel === 'sms'" class="conversation-channel-note">Appointment reminder and Y confirmation · Notifyre integration and recipient consent required.</p>
          <p v-else class="conversation-channel-note">Internal care-team coordination · Separate from the client’s secure conversation.</p>
          <article v-for="(message,index) in active.messages" :key="index" class="conversation-message"><ConversaSender :name="message.from" /><p>{{ message.text }}</p></article>
          <article v-if="replied.has(active.id)" class="conversation-message sample-reply"><ConversaSender name="Jordan Reed, LCSW" /><p>{{ active.sampleReply }}</p><small>Sample reply · Not sent</small></article>
          <div v-if="active.channel === 'sms'" class="confirmation-example"><ConversaIcon type="read" />Confirmed with Y · Fictional appointment</div>
          <div class="conversation-reply"><span>Reply to this conversation</span><p>{{ active.sampleReply }}</p><button type="button" :disabled="replied.has(active.id)" @click="previewReply">{{ replied.has(active.id) ? 'Example reply shown ✓' : 'Preview an example reply' }}</button></div>
        </template><p v-else class="empty-conversations">Choose an example conversation.</p>
        <p class="conversation-demo-note" role="status">{{ notice || 'Explore the channels, search and example replies. Nothing is sent or saved.' }}</p>
      </section>
    </div>
  </div>
</template>
<script setup>
import { computed, ref } from 'vue';
import ConversaBrand from '../../components/conversa/ConversaBrand.vue';
import ConversaBadge from '../../components/conversa/ConversaBadge.vue';
import ConversaIcon from '../../components/conversa/ConversaIcon.vue';
import ConversaSender from '../../components/conversa/ConversaSender.vue';
import SecureMessageBanner from '../../components/conversa/SecureMessageBanner.vue';
import '../../styles/conversa.css';
const channels=[{id:'all',label:'All'},{id:'secure',label:'Secure'},{id:'internal',label:'Internal'},{id:'sms',label:'SMS'}];
const conversations=[
  {id:'secure',channel:'secure',person:'Taylor Ellis · Guardian',subject:'Your between-session worksheet',preview:'A shared care conversation with the authorized family and care team.',unread:true,messages:[{from:'Jordan Reed, LCSW',text:'Hi Taylor, the grounding worksheet we practiced together is in Documents. We can review what felt useful at our next visit.'},{from:'Taylor Ellis · Guardian',text:'Thank you. I’ll bring my questions to our next session.'}],sampleReply:'That sounds good. We’ll make time to talk through them together.'},
  {id:'internal',channel:'internal',person:'Morgan Shaw · Supervisor',subject:'Co-sign review',preview:'A note and its session materials, ready for supervision.',unread:true,messages:[{from:'Morgan Shaw · Supervisor',text:'The progress note is ready for our review. Please keep the completed worksheet with the session materials so we can discuss the intervention and next steps.'}],sampleReply:'The worksheet is attached to the session. I’m ready to review the note with you.'},
  {id:'sms',channel:'sms',person:'Avery Chen · Client',subject:'Appointment confirmation',preview:'Y · Appointment confirmation reply',unread:false,messages:[{from:'Meadowbrook Therapy',text:'Your appointment is tomorrow at 10:00 AM. Reply Y to confirm. Reply STOP to opt out.'},{from:'Avery Chen · Client',text:'Y'}],sampleReply:'Thank you. Your appointment is confirmed.'}
];
const channel=ref('all'),folder=ref('all'),search=ref(''),selected=ref('secure'),replied=ref(new Set()),notice=ref('');
const visible=computed(()=>conversations.filter(item=>(channel.value==='all'||item.channel===channel.value)&&(folder.value!=='unread'||item.unread)&&`${item.person} ${item.subject}`.toLowerCase().includes(search.value.trim().toLowerCase())));
const active=computed(()=>visible.value.find(item=>item.id===selected.value));
function selectFirst(){if(!visible.value.some(item=>item.id===selected.value))selected.value=visible.value[0]?.id || '';notice.value='';}
function previewReply(){replied.value=new Set([...replied.value,active.value.id]);notice.value='Example reply shown locally. No message, notification or appointment update was sent.';}
function reset(){channel.value='all';folder.value='all';search.value='';selected.value='secure';replied.value=new Set();notice.value='';}
</script>
