ay:block;width:100%;font:inherit;color:inherit;text-align:left;background:white;border:1px solid #e1e8f0;border-radius:10px;padding:15px 12px;margin-bottom:10px;cursor:pointer}.conversation-list>button.selected{background:#edf4ff;border-color:#9cbee8;box-shadow:inset 3px 0 #2860a6}.conversation-row-heading{display:flex;align-items:center;gap:8px}.conversation-row-heading strong{display:block;font-size:11px;line-height:1.6}.conversation-row-heading span{display:block;font-size:10px;line-height:1.6;color:#526982;margin-top:3px}.conversation-list>button>p{font-size:10px;line-height:1.8;margin:12px 0;color:#64758b}.conversation-list>button>small{font-size:9px;display:block;margin-top:10px;color:#66768b}.conversation-reader{padding:24px;min-width:0}.conversation-reader-heading{display:flex;align-items:flex-start;gap:16px;justify-content:space-between}.conversation-reader-heading>div>p{font-size:8px;letter-spacing:1.3px;font-weight:700;color:#69829e;margin:0 0 8px}.conversation-reader-heading h3{font-size:21px;line-height:1.35;letter-spacing:-.5px;margin:0 0 16px}.conversation-reader :deep(.secure-message-banner){padding:14px;margin:0 0 20px}.conversation-reader :deep(.secure-message-banner__identity strong){font-size:14px}.conversation-reader :deep(.secure-message-banner__private){font-size:8px}.conversation-reader :deep(.secure-message-banner p){font-size:10px;line-height:1.8}.conversation-reader :deep(.secure-message-banner__seal){width:34px;height:34px}.conversation-message{padding:18px 0;border-bottom:1px solid #e4eaf2}.conversation-message>p{font-size:12px;line-height:1.9;color:#435b76;margin:12px 0 0;white-space:pre-wrap}.conversation-message :deep(.conversa-sender__details){font-size:11px}.conversation-channel-note{padding:12px 14px;background:#f3f7fc;border-radius:8px;font-size:11px;line-height:1.8;color:#5b6f88;margin:0 0 4px}.conversation-reply{border:1px solid #d8e3f0;background:#fbfdff;border-radius:10px;padding:16px;margin-top:22px}.conversation-reply>span{f