@container(max-width:900px){.conversation-layout{grid-template-columns:minmax(180px,.7fr) minmax(0,1.3fr)}.conversation-folders{display:none}.fictional-tag{display:none}.conversation-reader{padding:18px}}
@container(max-width:560px){.conversation-header{flex-wrap:wrap;padding:16px}.conversation-header>button{padding:8px;font-size:10px}.conversation-channels{padding:10px 12px;gap:4px}.conversation-channels button{padding:8px;font-size:11px}.conversation-layout{grid-template-columns:1fr}.conversation-list{border-right:0;border-bottom:1px solid #e1e7ef;padding:16px}.conversation-list>button{padding:12px}.conversation-list>button>p{display:none}.conversation-list>button>small{display:inline-block;margin-left:8px}.conversation-reader-heading{flex-wrap:wrap}.conversation-reader-heading h3{font-size:20px}.conversation-reader .conversation-reader-heading :deep(.conversa-badge){margin-bottom:12px}}
